+
+function httpsUrl(value: string | null | undefined): string | null {
+  if (!value) return null;
+  try {
+    const url = new URL(value);
+    return url.protocol === 'https:' ? url.toString() : null;
+  } catch {
+    return null;
+  }
+}
+
+export function neatlogsTraceUrl(traceId: string | null | undefined): string | null {
+  if (!traceId || !/^[0-9a-f]{32}$/i.test(traceId)) return null;
+  return `https://app.neatlogs.com/traces/${traceId}`;
+}
+
+export function entireSessionUrl(repoSlug: string | undefined, sessionId: string | null | undefined): string | null {
+  if (!repoSlug || !sessionId) return null;
+  const parts = repoSlug.split('/');
+  if (parts.length !== 2 || parts.some(part => !part || part === '.' || part === '..')) return null;
+  return `https://entire.io/gh/${parts.map(encodeURIComponent).join('/')}/session/${encodeURIComponent(sessionId)}`;
+}
+
+export function prEvidenceLinks(row: LedgerRow, config: TallyConfig): PrEvidenceLink[] {
+  const links: PrEvidenceLink[] = [];
+  if (config.integrations.entire) {
+    const checkpointUrl = httpsUrl(row.checkpointUrl) ?? entireSessionUrl(config.repo.slug, row.entireSessionId);
+    if (checkpointUrl) links.push({
+      label: 'Entire session and checkpoint',
+      url: checkpointUrl,
+      ...(row.checkpointId ? { note: `checkpoint ${row.checkpointId}` } : {}),
+    });
+  }
+  if (config.integrations.neatlogs) {
+    const decisionTraceUrl = httpsUrl(row.traceUrl) ?? neatlogsTraceUrl(row.traceId);
+    const workerTraceUrl = httpsUrl(row.workerTraceUrl) ?? neatlogsTraceUrl(row.workerTraceId);
+    if (decisionTraceUrl) links.push({ label: 'Neatlogs routing trace', url: decisionTraceUrl });
+    if (workerTraceUrl) links.push({ label: 'Neatlogs worker trace', url: workerTraceUrl });
+  }
+  if (config.integrations.cfoai || config.budget.source === 'cfoai') {
+    const budgetUrl = httpsUrl(config.budget.cfoai?.tableUrl);
+    const spendUrl = httpsUrl(config.budget.cfoai?.spendDetailTableUrl);
+    if (budgetUrl) links.push({ label: 'cfo.ai budget table', url: budgetUrl });
